//! Composition (design: Layers): which entries apply to some agents in one place, in what order, and where
//! each output line comes from. Harness-neutral: adapters (adapters.rs) decide where the text goes.

use crate::model::{Audience, Entry, Kind, Scope, Visibility};
use crate::stack::Stacks;
use serde::Serialize;
use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

pub const BEGIN: &str = "<!-- lords-command:begin -->";
pub const END: &str = "<!-- lords-command:end -->";
const HEADER: &str =
    "<!-- Generated by Lords Command from its stacks; change an entry there, then sync. -->";

const MEMORY_INTRO: &str = "Notes agents wrote down earlier. Read a note's file when its topic comes up; notes are not rules.";

/// The line that stands for notes meant for one role, when the reader's role is unknown: how many per role, and
/// the dirs they are in.
fn role_pointer(notes: &[&Entry], ctx: &Context) -> Option<String> {
    if notes.is_empty() {
        return None;
    }
    let mut counts: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    let mut dirs: Vec<String> = Vec::new();
    for e in notes {
        for r in &e.meta.roles {
            *counts.entry(r.as_str()).or_default() += 1;
        }
        let dir = e.body_file.parent().map(|d| shown(d, ctx)).unwrap_or_default();
        if !dirs.contains(&dir) {
            dirs.push(dir);
        }
    }
    let counts: Vec<String> =
        default_first(counts, ctx).iter().map(|(r, n)| format!("{r}: {n}")).collect();
    let dirs: Vec<String> = dirs.iter().map(|d| format!("`{d}`")).collect();
    Some(format!(
        "- More notes are for one role only ({}); in that role, find them in {} (each file's `roles` says whose).",
        counts.join(", "),
        dirs.join(", ")
    ))
}

const INTENT_INTRO: &str =
    "The owner's intent, binding. Read an entry's file before work its subject touches; the file is the full text.";

/// The longest hook an index line shows; the file it points to has the whole description.
pub const HOOK_CHARS: usize = 100;

/// A hook cut at a word boundary to at most `HOOK_CHARS` characters, with "…" when cut.
fn short_hook(hook: &str) -> String {
    if hook.chars().count() <= HOOK_CHARS {
        return hook.to_string();
    }
    let cut: String = hook.chars().take(HOOK_CHARS).collect();
    let at_word =
        cut.rfind(' ').filter(|i| *i > HOOK_CHARS / 2).map_or(cut.as_str(), |i| &cut[..i]);
    format!("{}…", at_word.trim_end_matches([',', ';', ':', ' ', '-', '—']))
}

/// A path as composed text shows it: the platform's separators, and relative to `relative_to` when the context
/// sets it (the one switch to relative paths, once a harness is shown to resolve them; docs/load-order.md).
fn shown(p: &Path, ctx: &Context) -> String {
    let rel = ctx.relative_to.as_deref().and_then(|base| relative(p, base));
    let path = rel.as_deref().unwrap_or(p).to_string_lossy().into_owned();
    if cfg!(windows) {
        path.replace('/', "\\")
    } else {
        path
    }
}

/// `p` from `base` (`..` up to their common dir), or `None` when they share no root (another drive).
fn relative(p: &Path, base: &Path) -> Option<PathBuf> {
    use std::path::Component;
    let key = |c: Component| {
        let s = c.as_os_str().to_string_lossy().into_owned();
        if cfg!(windows) {
            s.to_lowercase()
        } else {
            s
        }
    };
    let (a, b): (Vec<Component>, Vec<Component>) =
        (p.components().collect(), base.components().collect());
    let common = a.iter().zip(&b).take_while(|(x, y)| key(**x) == key(**y)).count();
    if common == 0 {
        return None;
    }
    let mut out = PathBuf::new();
    for _ in common..b.len() {
        out.push("..");
    }
    for c in &a[common..] {
        out.push(c.as_os_str());
    }
    Some(if out.as_os_str().is_empty() { PathBuf::from(".") } else { out })
}

/// Where an index line's file is: the dir its group names once, and the file's path within it. A skill's file is
/// `<name>/SKILL.md` in its skills dir; any other entry's is its file name in its own dir.
fn index_place(e: &Entry) -> (PathBuf, PathBuf) {
    let file = &e.body_file;
    let up = if e.meta.kind == Kind::Skill { 2 } else { 1 };
    let mut dir = file.as_path();
    for _ in 0..up {
        dir = dir.parent().unwrap_or(dir);
    }
    (dir.to_path_buf(), file.strip_prefix(dir).unwrap_or(file).to_path_buf())
}

/// An index entry's display name, when its file follows from it (a note's `<name>.md`, a skill's
/// `<name>/SKILL.md`).
fn named_file(e: &Entry, name: &str) -> PathBuf {
    match e.meta.kind {
        Kind::Skill => Path::new(name).join("SKILL.md"),
        _ => PathBuf::from(format!("{name}.md")),
    }
}

/// Index lines grouped by dir: each dir is named once ("In `<dir>`:"), each line ends with its file within it, or
/// with nothing when its name gives the file (the group line says how). `items`: the entry and the line's text.
fn push_index(
    items: &[(&Entry, String, Option<String>)],
    ctx: &Context,
    lines: &mut Vec<String>,
    out: &mut Composed,
) {
    let mut current: Option<PathBuf> = None;
    for (i, (e, text, name)) in items.iter().enumerate() {
        let (dir, file) = index_place(e);
        if current.as_ref() != Some(&dir) {
            let named = |x: &(&Entry, String, Option<String>)| {
                x.2.as_deref()
                    .is_some_and(|n| index_place(x.0) == (dir.clone(), named_file(x.0, n)))
            };
            let rest = &items[i..];
            let group = rest.iter().take_while(|x| index_place(x.0).0 == dir);
            let how = if group.clone().any(named) {
                let pattern = match e.meta.kind {
                    Kind::Skill => shown(&Path::new("<name>").join("SKILL.md"), ctx),
                    _ => "<name>.md".to_string(),
                };
                format!(", as `{pattern}`")
            } else {
                String::new()
            };
            lines.push(format!("In `{}`{how}:", shown(&dir, ctx)));
            current = Some(dir.clone());
        }
        let follows = name.as_deref().is_some_and(|n| named_file(e, n) == file);
        if follows {
            lines.push(format!("- {text}"));
        } else {
            lines.push(format!("- {text} (`{}`)", shown(&file, ctx)));
        }
        out.sources.push(Source {
            line: lines.len(),
            id: e.id().to_string(),
            stack: e.stack,
            file: e.body_file.clone(),
            file_line: 1,
        });
        out.ids.push(e.id().to_string());
    }
}

/// Memory or skill index entries, each with its line's text and the name its file may follow from.
fn index_items<'e>(entries: &[&'e Entry]) -> Vec<(&'e Entry, String, Option<String>)> {
    entries
        .iter()
        .map(|e| {
            let (name, text) = index_item(e);
            (*e, text, Some(name))
        })
        .collect()
}

/// The line that stands for everything for only some roles in a place's file: each role's file carries it in
/// full; how many entries and notes each has. `pointed`: each entry with the roles it is pointed to for (an entry
/// whose lines go to several roles counts once for each).
fn role_files_line(pointed: &[(&Entry, &[String])], dir: &Path, ctx: &Context) -> String {
    let mut ids: std::collections::BTreeMap<&str, BTreeSet<&str>> =
        std::collections::BTreeMap::new();
    for (e, roles) in pointed {
        for r in roles.iter() {
            ids.entry(r.as_str()).or_default().insert(e.id());
        }
    }
    let counts = ids.into_iter().map(|(r, es)| (r, es.len())).collect();
    let files: Vec<String> = default_first(counts, ctx)
        .iter()
        .map(|(r, n)| {
            let here = if ctx.default_role.as_deref() == Some(*r) {
                ", the default role here"
            } else {
                ""
            };
            format!("`{}` ({n}{here})", crate::sync::role_file(r))
        })
        .collect();
    format!(
        "More rules, facts, status and notes bind only some roles; each role's file in `{}` has them in full: {}.",
        shown(dir, ctx),
        files.join(", ")
    )
}

/// A memory or skill index entry: its name and the line's text (name and one-line hook).
fn index_item(e: &Entry) -> (String, String) {
    // A skill's own SKILL.md frontmatter names and describes it, as the harness shows it.
    let own = |key: &str| -> Option<String> {
        let yaml = crate::frontmatter::split(&e.body).yaml?;
        yaml.lines().find_map(|l| {
            l.strip_prefix(key)
                .and_then(|rest| rest.strip_prefix(':'))
                .map(|v| v.trim().trim_matches(['"', '\'']).to_string())
        })
    };
    let skill = e.meta.kind == Kind::Skill;
    let name = e
        .meta
        .name
        .clone()
        .or_else(|| skill.then(|| own("name")).flatten())
        .unwrap_or_else(|| e.id().trim_start_matches("memory.").to_string());
    let described =
        e.meta.description.clone().or_else(|| skill.then(|| own("description")).flatten());
    let hook = short_hook(described.as_deref().unwrap_or(&e.meta.title));
    let text = if hook.trim().is_empty() || hook == name {
        name.clone()
    } else {
        format!("{name}: {hook}")
    };
    (name, text)
}

/// Kinds composed into instruction text, in section order. A template is composed only once it has a class (its
/// line, or its index entry); before, as ever, not at all.
const SECTIONS: [(Kind, &str); 6] = [
    (Kind::Intent, "Owner intent"),
    (Kind::Role, "Roles"),
    (Kind::Rule, "Rules"),
    (Kind::Fact, "Facts"),
    (Kind::Status, "Status"),
    (Kind::Template, "Templates"),
];

/// The line that names, once, how to open an entry by id (the brief, slice 3), when a composition has lines or
/// index entries.
fn opener_line(ctx: &Context) -> String {
    // A public file names no user path (design: Privacy).
    let exe = match &ctx.opener {
        Some(p) if !ctx.public_only => shown(p, ctx),
        _ => "lords".to_string(),
    };
    // The owner's agreed reading of 8 Nov (intent.owner-decisions-2026-11-08 item 11): the boundaries stay absolute,
    // everything else is guidance to follow by its purpose, and an agent that departs from it says so. With the shorter
    // start intro, no longer than the two lines it replaces: it is in every start, and the orchestrator's has a few
    // characters to spare.
    format!(
        "Each line below is an entry's short form. Boundaries (the owner's reserved decisions, credentials, history rewrites, machine safety) are absolute; the rest is guidance: follow its purpose, say where you depart. Full entry: `{exe} show <id>`."
    )
}

/// The first line of a native child's start file: its role, and how the place's file it also reads applies to it.
/// A launched start doesn't send the session to its whole role file, since it and the place's file carry every core
/// line of the role; a native child's still names that file (its spec: tests/core_lines.rs, the native child's start).
fn child_intro(role: &str, start: ChildStart) -> String {
    match start {
        ChildStart::Beyond => format!(
            "You start as a {role} here, a native subagent: these lines and the place's file apply to you, except its lines marked for other roles. Your role's whole start file is `role-{role}.md` in the place's `.lords` dir."
        ),
        ChildStart::Whole => {
            format!("You start as a {role} here, a native subagent: this is your role's whole start.")
        }
        ChildStart::Launched => {
            let a = if role.starts_with(['a', 'e', 'i', 'o', 'u']) { "an" } else { "a" };
            format!(
                "You start as {a} {role} here, the role named at launch: these lines and the place's file apply to you, except its lines marked for other roles."
            )
        }
    }
}

/// One part of an entry with a class (core_lines.rs): one of its lines, or its index entry, for these roles.
struct Part<'e> {
    e: &'e Entry,
    line: Option<&'e str>,
    /// The readers of this composition it is for.
    roles: Vec<String>,
    /// Every role it is for: a line's, or for the index entry, each role the entry binds that no line is for.
    of: Vec<String>,
}

/// The parts a classified entry gives a composition: for a known role, its lines for that role, or else its index
/// entry; for an unknown one, every line for the roles it names, and the index entry for the roles no line is for.
fn parts<'e>(e: &'e Entry, ctx: &Context, declared: &[String]) -> Vec<Part<'e>> {
    let bound = crate::core_lines::bound(e, declared);
    let readers: Vec<String> = match &ctx.roles {
        Some(roles) => bound.iter().filter(|r| roles.contains(r)).cloned().collect(),
        None => bound.clone(),
    };
    let lines: Vec<(&str, Vec<String>)> = crate::core_lines::lines(e)
        .into_iter()
        .map(|(line, roles)| (line, if roles.is_empty() { bound.clone() } else { roles.to_vec() }))
        .collect();
    let unlined: Vec<String> =
        bound.iter().filter(|r| !lines.iter().any(|(_, of)| of.contains(r))).cloned().collect();
    let mut out = Vec::new();
    for (line, of) in lines {
        let roles: Vec<String> = of.iter().filter(|r| readers.contains(r)).cloned().collect();
        if !roles.is_empty() {
            out.push(Part { e, line: Some(line), roles, of });
        }
    }
    // A known role sees one form of each entry: its lines, or its index entry.
    let roles: Vec<String> = unlined.iter().filter(|r| readers.contains(r)).cloned().collect();
    if !roles.is_empty() && (ctx.roles.is_none() || out.is_empty()) {
        out.push(Part { e, line: None, roles, of: unlined });
    }
    out
}

/// A part's bullet: the id, a label where it is for only some readers, and its line or its title.
fn part_line(p: &Part, ctx: &Context, stacks: &Stacks, development: &[String]) -> String {
    let who = only_for(p.e, &p.roles, ctx, development);
    let temp = crate::temporary::label(p.e, stacks);
    let label = match (who, temp) {
        (Some(who), Some(t)) => format!(" ({who} only; {t})"),
        (Some(who), None) => format!(" ({who} only)"),
        (None, Some(t)) => format!(" ({t})"),
        (None, None) => String::new(),
    };
    let text = match p.line {
        Some(l) => l.replace(['\r', '\n'], " "),
        None => p.e.meta.title.clone(),
    };
    format!("- {}{label}: {}", p.e.id(), text.trim())
}

/// Which layers a composition takes.
#[derive(Clone, Debug)]
pub enum Layers {
    /// User-level files, which every run on the machine reads (product turns too, backbone requirement BB-5): only global entries
    /// for every role, and no memory. See `user_level`.
    Global,
    /// A repo's own files: its project, the repo, path entries covering `sub`, and the global entries the user
    /// level leaves out (role-specific ones and memory). With `global`, every global entry (a file that must
    /// stand alone: a tracked AGENTS.md, a role file a brief points to).
    Repo { repo: String, project: Option<String>, sub: Option<String>, global: bool },
    /// A working dir with no git repo (e.g. a harness dir): like a repo, with its own workspace layer.
    Workspace { name: String, project: Option<String>, global: bool },
}

/// Whether an entry suits every run on the machine, so it may go to user-level files and skill dirs: a global
/// entry for every role (no `roles`) that is no memory note. A skill with roles installs per checkout instead.
pub fn user_level(e: &Entry) -> bool {
    matches!(e.scope, Scope::Global) && e.meta.roles.is_empty() && e.meta.kind != Kind::Memory
}

#[derive(Clone, Debug)]
pub struct Context {
    pub audience: Vec<Audience>,
    pub layers: Layers,
    /// Only entries from the public stack (a tracked file anyone can read).
    pub public_only: bool,
    /// Memory stores the target's harness already loads by itself: left out of the memory index.
    pub skip_stores: Vec<String>,
    /// The role whoever reads the file has (`None`: unknown). A known role gets only entries for it (or for
    /// every role); with an unknown one, role-specific entries are labelled, and role-specific notes are left out
    /// of the memory index for a pointer to them.
    pub roles: Option<Vec<String>>,
    /// For files every role reads whole, under a byte limit for some harnesses (a place's agent files): owner
    /// intent, and entries for only some roles, as index lines (title and file, read on demand) instead of their
    /// text. Role files and user-level files carry the text.
    pub by_reference: bool,
    /// With `by_reference`, the dir of this place's role files: entries and notes for only some roles are then
    /// left out for one line that points there (each role file carries them in full).
    pub role_dir: Option<PathBuf>,
    /// Paths shown relative to this dir instead of absolute (see `shown`).
    pub relative_to: Option<PathBuf>,
    /// With `role_dir`, the role a reader without a brief has (the place's `default_role`): with
    /// `default_role_inline` its entries and notes stay inline, labelled; without, they go behind the role-files
    /// line like the others', and that line (and the notes line) names this role first.
    pub default_role: Option<String>,
    /// Whether the adapter's file carries the default role inline (`Adapter::default_role_inline`).
    pub default_role_inline: bool,
    /// The `lords` the composed file names to open an entry by id (`opener_line`): the installed guard copy.
    pub opener: Option<PathBuf>,
    /// A native child's start file (with `roles` its one role), after a line naming the role (`child_intro`).
    pub child: Option<ChildStart>,
    /// In a place's file, whether the default role's lines for only some roles show (labelled) or stay in its role
    /// file like any other role's (stack.toml `place_files.<adapter>.default_role_lines`).
    pub default_role_lines: bool,
    /// The file the Memory section goes to (stack.toml `place_files.<adapter>.memory = "pointer"`): the composition
    /// then shows one line naming it, and `Composed::memory` is that file's text.
    pub memory_file: Option<PathBuf>,
}

/// Which start file a native child gets (sync.rs `CHILD_FILE`, `CHILD_WHOLE_FILE`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChildStart {
    /// For a child that also loads the place's file: what of its role that file doesn't carry, its entries and lines
    /// for only some development roles.
    Beyond,
    /// For a child that loads no place file (Claude Code's Explore and Plan): its role's whole start, as its role
    /// file has it, without the notes.
    Whole,
    /// For a session whose launch names its role (a T3-delegated one; sync.rs `start_file`): what `Beyond` holds, after
    /// a line naming the role as named at launch.
    Launched,
}

impl ChildStart {
    /// Whether the reader also loads the place's file, so the start leaves out what that file carries.
    fn beside_place_file(self) -> bool {
        matches!(self, ChildStart::Beyond | ChildStart::Launched)
    }
}

impl Context {
    /// The default role, where its entries and notes stay inline.
    fn inline_role(&self) -> Option<&String> {
        self.default_role.as_ref().filter(|_| self.default_role_inline && self.role_dir.is_some())
    }
}

/// Roles and their counts, the default role first, then by name.
fn default_first<'a>(
    counts: std::collections::BTreeMap<&'a str, usize>,
    ctx: &Context,
) -> Vec<(&'a str, usize)> {
    let mut v: Vec<(&str, usize)> = counts.into_iter().collect();
    v.sort_by_key(|(r, _)| ctx.default_role.as_deref() != Some(*r));
    v
}

#[derive(Clone, Debug, Serialize)]
pub struct Source {
    /// 1-based line in the composed text.
    pub line: usize,
    pub id: String,
    pub stack: Visibility,
    pub file: PathBuf,
    pub file_line: usize,
}

#[derive(Clone, Debug, Default)]
pub struct Composed {
    /// The block, markers included; empty when nothing applies.
    pub text: String,
    pub sources: Vec<Source>,
    /// Ids composed, in order.
    pub ids: Vec<String>,
    /// Ids dropped because an applicable entry overrides them.
    pub overridden: Vec<String>,
    /// Applicable skills (installed as links, not composed into text).
    pub skills: Vec<String>,
    /// With `Context::memory_file`, that file's text: the Memory section in a managed block. `None` without a section.
    pub memory: Option<String>,
}

fn in_layers(e: &Entry, layers: &Layers) -> bool {
    scope_in_layers(&e.scope, layers, user_level(e))
}

/// Whether something of `scope` belongs in `layers`; `user_level`: it suits every run (see `user_level`).
fn scope_in_layers(scope: &Scope, layers: &Layers, user_level: bool) -> bool {
    match (layers, scope) {
        (Layers::Global, _) => user_level,
        (Layers::Workspace { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Workspace { name, .. }, Scope::Workspace(w)) => w == name,
        (Layers::Workspace { global, .. }, Scope::Global) => *global || !user_level,
        (Layers::Workspace { .. }, _) => false,
        (Layers::Repo { project, .. }, Scope::Project(p)) => project.as_deref() == Some(p),
        (Layers::Repo { repo, .. }, Scope::Repo(r)) => r == repo,
        (Layers::Repo { repo, sub, .. }, Scope::Path { repo: r, sub: s }) => {
            r == repo
                && sub
                    .as_deref()
                    .is_some_and(|here| here == s || here.starts_with(&format!("{s}/")))
        }
        (Layers::Repo { global, .. }, Scope::Global) => *global || !user_level,
        (Layers::Repo { .. }, Scope::Workspace(_)) => false,
    }
}

fn reaches(e: &Entry, audience: &[Audience]) -> bool {
    e.meta.audience.contains(&Audience::All) || e.meta.audience.iter().any(|a| audience.contains(a))
}

/// The label for an entry meant for only some of a target's audiences (Sol and Astra share one file).
/// The label for an entry meant for only some of a file's readers: the agents (Sol and Astra share one file)
/// and, where the file's role is unknown, the roles.
/// The role that product runs have (backbone requirement BB-4). Place files never reach product runs (BB-5), so an entry for every
/// other role needs no role label there.
pub const PRODUCT_ROLE: &str = "product";

/// `roles`: the roles the text is for (the entry's, or one core line's).
fn only_for(e: &Entry, roles: &[String], ctx: &Context, development: &[String]) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(agents) = only_agents(e, &ctx.audience) {
        parts.push(agents);
    }
    let every_development_role =
        !development.is_empty() && development.iter().all(|r| roles.contains(r));
    if ctx.roles.is_none() && !roles.is_empty() && !every_development_role {
        parts.push(roles.join(", "));
    }
    (!parts.is_empty()).then(|| parts.join("; "))
}

fn only_agents(e: &Entry, audience: &[Audience]) -> Option<String> {
    if e.meta.audience.contains(&Audience::All)
        || audience.iter().all(|a| e.meta.audience.contains(a))
    {
        return None;
    }
    let names: Vec<&str> = e
        .meta
        .audience
        .iter()
        .filter(|a| audience.contains(a))
        .map(|a| match a {
            Audience::Opus => "Opus",
            Audience::Sol => "Sol",
            Audience::Astra => "Astra",
            Audience::All => "all",
        })
        .collect();
    Some(names.join(", "))
}

pub fn applicable<'a>(stacks: &'a Stacks, ctx: &Context) -> Vec<&'a Entry> {
    applicable_on(stacks, ctx, &crate::ops::today())
}

/// `applicable` on the date `today` (`YYYY-MM-DD`): one date for compositions that are compared (gap 11, §0d.5).
pub fn applicable_on<'a>(stacks: &'a Stacks, ctx: &Context, today: &str) -> Vec<&'a Entry> {
    stacks
        .entries()
        .filter(|e| e.active())
        .filter(|e| !ctx.public_only || e.stack == Visibility::Public)
        .filter(|e| in_layers(e, &ctx.layers) && reaches(e, &ctx.audience))
        .filter(|e| for_role(e, ctx))
        // An ended temporary entry is never composed (it is retired at the next sync).
        .filter(|e| crate::temporary::ended(e, stacks, today).is_none())
        .collect()
}

/// A known role takes entries for it or for every role; an unknown one keeps them all (labelled, or pointed to).
fn for_role(e: &Entry, ctx: &Context) -> bool {
    match &ctx.roles {
        None => true,
        // A note for every role is a development note: product runs get none (orchestrator, 25 Oct).
        Some(roles) if e.meta.roles.is_empty() => {
            e.meta.kind != Kind::Memory || roles.iter().any(|r| r != PRODUCT_ROLE)
        }
        Some(roles) => e.meta.roles.iter().any(|r| roles.contains(r)),
    }
}

/// The memory stores marked `live`: their agents keep their own `MEMORY.md` current (orchestrator, 30 Oct, item 3).
pub fn live_stores(stacks: &Stacks) -> impl Iterator<Item = &crate::stack::MemoryStore> {
    stacks.private.iter().flat_map(|p| p.manifest.memory_stores.iter()).filter(|m| m.live)
}

/// A live store's index: `MEMORY.md` in its own dir.
pub fn live_index(m: &crate::stack::MemoryStore) -> PathBuf {
    crate::config::expand_home(&m.path).join("MEMORY.md")
}

/// Why a live store's index can't be named, if it can't: it must be a readable plain file (Codex switch-on review r1,
/// R2).
pub fn live_index_problem(m: &crate::stack::MemoryStore) -> Option<String> {
    let index = live_index(m);
    match crate::fsguard::read(&index) {
        Ok(Some(_)) => None,
        Ok(None) => {
            Some(format!("memory store {}: its live index {} is missing", m.name, index.display()))
        }
        Err(e) => Some(format!("memory store {}: its live index can't be read ({e})", m.name)),
    }
}

pub fn compose(stacks: &Stacks, ctx: &Context) -> Composed {
    compose_on(stacks, ctx, &crate::ops::today())
}

/// `compose` on the date `today`, which decides which temporary entries have ended (gap 11, §0d.5: a start and its
/// baseline are composed on one date).
pub fn compose_on(stacks: &Stacks, ctx: &Context, today: &str) -> Composed {
    let mut development: Vec<String> = stacks
        .all()
        .flat_map(|s| s.manifest.roles.iter())
        .filter(|r| *r != PRODUCT_ROLE)
        .cloned()
        .collect();
    development.sort();
    development.dedup();
    // A live store's imported copies take no part in composition (Codex switch-on review r1, R4): its own index is
    // the one source, named in Memory below, so its lagging copies never render, not as notes, extensions or overrides.
    let live_store = |e: &Entry| match &e.meta.origin {
        crate::model::Origin::Imported { store, .. } => {
            live_stores(stacks).any(|m| m.name == *store)
        }
        _ => false,
    };
    let all: Vec<&Entry> =
        applicable_on(stacks, ctx, today).into_iter().filter(|e| !live_store(e)).collect();
    let overridden: BTreeSet<&str> =
        all.iter().flat_map(|e| e.meta.overrides.iter().map(String::as_str)).collect();
    let live: Vec<&Entry> = all.into_iter().filter(|e| !overridden.contains(e.id())).collect();
    // For only some of the development roles, where the reader's role is unknown.
    let partial = |roles: &[String]| {
        ctx.roles.is_none() && !roles.is_empty() && !development.iter().all(|r| roles.contains(r))
    };
    let partial_role = |e: &Entry| partial(&e.meta.roles);
    // An entry with a class goes by its parts (its lines, its index entry); any other by its whole text, as before.
    let by_parts = |e: &Entry| crate::core_lines::classified(e) && e.meta.kind != Kind::Intent;
    // A native child's file leaves out the notes; the one for a child that also reads the place's file leaves out what
    // that file carries for every role too: intent, skills without a class (each is listed there), and whatever is for
    // every development role (an entry with a class keeps its other parts, below; sol-loop r1, S2: a skill's line
    // for the child's role alone).
    let every_development = |roles: &[String]| development.iter().all(|r| roles.contains(r));
    let beyond = ctx.child.is_some_and(ChildStart::beside_place_file);
    let live: Vec<&Entry> = match ctx.child {
        Some(ChildStart::Beyond | ChildStart::Launched) => live
            .into_iter()
            .filter(|e| !matches!(e.meta.kind, Kind::Intent | Kind::Memory))
            .filter(|e| e.meta.kind != Kind::Skill || by_parts(e))
            .filter(|e| {
                by_parts(e) || !(e.meta.roles.is_empty() || every_development(&e.meta.roles))
            })
            .collect(),
        Some(ChildStart::Whole) => {
            live.into_iter().filter(|e| e.meta.kind != Kind::Memory).collect()
        }
        None => live,
    };
    // Where role files exist, their entries and notes stay there: one line points to them (orchestrator, 25 Oct:
    // cut "index lines that the role files already carry in full").
    let place_file = ctx.role_dir.is_some() && ctx.by_reference;
    let (pointed, live): (Vec<&Entry>, Vec<&Entry>) = match &ctx.role_dir {
        Some(_) if ctx.by_reference => live.into_iter().partition(|e| {
            partial_role(e)
                && !by_parts(e)
                && !matches!(e.meta.kind, Kind::Intent | Kind::Skill)
                && !ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d))
        }),
        _ => (Vec::new(), live),
    };
    // Each part shows here unless, in a place's file, it is for only some roles and not the default role's: then its
    // roles' files carry it. A line is short, so the default role's lines show in every adapter's file alike, unless
    // the stack leaves them out of one adapter's (`default_role_lines`, the Lords owner, 31 Oct: Codex headroom).
    let declared = crate::sync::declared_roles(stacks);
    let stays = |p: &Part| {
        place_file
            && partial(&p.roles)
            && !(ctx.default_role_lines
                && ctx.default_role.as_ref().is_some_and(|d| p.roles.contains(d)))
    };
    let mut shown_parts: std::collections::BTreeMap<&str, Vec<Part>> = Default::default();
    let mut pointed_parts: Vec<Part> = Vec::new();
    for e in live.iter().copied().filter(|e| by_parts(e)) {
        for p in
            parts(e, ctx, &declared).into_iter().filter(|p| !(beyond && every_development(&p.of)))
        {
            // A skill is listed wherever it applies; a line not for this file's readers leaves its own hook there, and
            // is counted for the role file that has it (repair sol-loop r1, R1).
            if stays(&p) {
                pointed_parts.push(p);
            } else {
                shown_parts.entry(e.id()).or_default().push(p);
            }
        }
    }
    // Whether something here goes by its id: a line, or an index entry (a skill's index entry is its own hook line).
    let opens =
        shown_parts.values().flatten().any(|p| p.e.meta.kind != Kind::Skill || p.line.is_some());
    let has_line =
        |e: &Entry| shown_parts.get(e.id()).is_some_and(|ps| ps.iter().any(|p| p.line.is_some()));
    let mut out = Composed {
        overridden: overridden.iter().map(|s| s.to_string()).collect(),
        skills: live
            .iter()
            .filter(|e| e.meta.kind == Kind::Skill)
            .map(|e| e.id().to_string())
            .collect(),
        ..Composed::default()
    };
    // Whether an entry shows in its section (`SECTIONS`): by its whole text, or by a line (an index entry shows in the
    // index; skills and notes in their own indexes). A template shows only once it has a class.
    let in_section = |e: &Entry| {
        if !SECTIONS.iter().any(|(k, _)| *k == e.meta.kind) {
            false
        } else if by_parts(e) {
            has_line(e)
        } else {
            e.meta.kind != Kind::Template
        }
    };
    // An extension follows its parent where the parent's own form there carries it; otherwise it stands in its own
    // place (sol-loop r1, S1: one whose parent is only in the index was dropped; r2, T1: one whose parent is a skill).
    // An intent shown as a title carries only intents shown as titles, and a parent shown by its text carries none:
    // anything else would lose its line or text there (review r1, F2), or show a title's text (repair r1, R6).
    let ids: BTreeSet<&str> = live.iter().filter(|e| in_section(e)).map(|e| e.id()).collect();
    let titled: BTreeSet<&str> = live
        .iter()
        .filter(|e| {
            e.meta.kind == Kind::Intent
                && (ctx.by_reference || e.meta.start == Some(crate::model::Start::Detail))
        })
        .map(|e| e.id())
        .collect();
    let extension_of = |e: &Entry, ids: &BTreeSet<&str>| -> Option<String> {
        e.meta
            .extends
            .first()
            .filter(|t| ids.contains(t.as_str()))
            .filter(|t| titled.contains(t.as_str()) == titled.contains(e.id()))
            .cloned()
    };

    let mut lines: Vec<String> = Vec::new();
    let pointed_roles: Vec<(&Entry, &[String])> = pointed
        .iter()
        .map(|e| (*e, e.meta.roles.as_slice()))
        .chain(pointed_parts.iter().map(|p| (p.e, p.roles.as_slice())))
        .collect();
    if let (Some(dir), false) = (&ctx.role_dir, pointed_roles.is_empty()) {
        lines.push(role_files_line(&pointed_roles, dir, ctx));
    }
    // A part's bullet, after a blank line where it starts a list.
    let push_part = |p: &Part, lines: &mut Vec<String>, out: &mut Composed| {
        if lines.last().is_some_and(|l| !l.starts_with("- ")) {
            lines.push(String::new());
        }
        lines.push(part_line(p, ctx, stacks, &development));
        out.sources.push(Source {
            line: lines.len(),
            id: p.e.id().to_string(),
            stack: p.e.stack,
            file: p.e.body_file.clone(),
            file_line: p.e.body_line,
        });
        if out.ids.last().map(String::as_str) != Some(p.e.id()) {
            out.ids.push(p.e.id().to_string());
        }
    };
    let push_entry = |e: &Entry, lines: &mut Vec<String>, out: &mut Composed| {
        if by_parts(e) {
            for p in shown_parts.get(e.id()).into_iter().flatten().filter(|p| p.line.is_some()) {
                push_part(p, lines, out);
            }
            return;
        }
        let who = only_for(e, &e.meta.roles, ctx, &development);
        let temp = crate::temporary::label(e, stacks);
        // In a file every role reads under a byte limit, an entry for only some roles is a reference; the role
        // files of the roles it binds carry its text.
        let inline_here =
            ctx.role_dir.is_some() && ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d));
        if ctx.by_reference && partial_role(e) && !inline_here {
            let who = who.unwrap_or_else(|| e.meta.roles.join(", "));
            let temp = temp.map(|t| format!("; {t}")).unwrap_or_default();
            let path = shown(&e.body_file, ctx);
            lines.push(format!("- ({who} only{temp}) {} (`{path}`)", e.meta.title));
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: e.body_line,
            });
            out.ids.push(e.id().to_string());
            return;
        }
        match (who, temp) {
            (Some(who), Some(t)) => lines.push(format!("({who} only; {t})")),
            (Some(who), None) => lines.push(format!("({who} only)")),
            (None, Some(t)) => lines.push(format!("({t})")),
            (None, None) => {}
        }
        // One text whichever line endings the file was checked out with (gap 11 r6, R5-F1): with CRLF a leading blank
        // line is "\r\n", which `trim_matches('\n')` keeps, so normalize first, as `core_lines::show` does.
        let body = e.body.replace("\r\n", "\n");
        for (i, l) in body.trim_matches('\n').lines().enumerate() {
            lines.push(l.trim_end_matches('\r').to_string());
            out.sources.push(Source {
                line: lines.len(),
                id: e.id().to_string(),
                stack: e.stack,
                file: e.body_file.clone(),
                file_line: e.body_line + i,
            });
        }
        out.ids.push(e.id().to_string());
    };

    let in_order = |a: &&Entry, b: &&Entry| {
        (a.rank(), a.meta.order.unwrap_or(0), a.id()).cmp(&(
            b.rank(),
            b.meta.order.unwrap_or(0),
            b.id(),
        ))
    };
    for (kind, heading) in SECTIONS {
        let mut section: Vec<&Entry> = live
            .iter()
            .copied()
            .filter(|e| e.meta.kind == kind && extension_of(e, &ids).is_none() && in_section(e))
            .collect();
        if section.is_empty() {
            continue;
        }
        section.sort_by(in_order);
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push(format!("# {heading}"));
        if kind == Kind::Intent {
            // In a place's file every intent is a title in the index (orchestrator T1, 25 Oct); elsewhere one whose
            // class is `detail` (plan L8), and the rest by their whole text, after it.
            let (indexed, whole): (Vec<&Entry>, Vec<&Entry>) = section.into_iter().partition(|e| {
                ctx.by_reference || e.meta.start == Some(crate::model::Start::Detail)
            });
            if !indexed.is_empty() {
                lines.push(String::new());
                lines.push(INTENT_INTRO.into());
                lines.push(String::new());
                let mut items = Vec::new();
                for e in indexed {
                    let mut ext: Vec<&Entry> = live
                        .iter()
                        .copied()
                        .filter(|x| extension_of(x, &ids).as_deref() == Some(e.id()))
                        .collect();
                    ext.sort_by_key(|x| x.id().to_string());
                    for x in std::iter::once(e).chain(ext) {
                        let temp = crate::temporary::label(x, stacks)
                            .map(|t| format!(" ({t})"))
                            .unwrap_or_default();
                        items.push((x, format!("{}{temp}", x.meta.title), None));
                    }
                }
                push_index(&items, ctx, &mut lines, &mut out);
            }
            section = whole;
        }
        for e in section {
            if !by_parts(e) {
                lines.push(String::new());
            }
            push_entry(e, &mut lines, &mut out);
            // Extensions follow the entry they extend, in id order.
            let mut ext: Vec<&Entry> = live
                .iter()
                .copied()
                .filter(|x| extension_of(x, &ids).as_deref() == Some(e.id()) && in_section(x))
                .collect();
            ext.sort_by_key(|x| x.id().to_string());
            for x in ext {
                push_entry(x, &mut lines, &mut out);
            }
        }
    }
    // The index of the rest (plan L8): each entry with a class that has no line here, by id and title, in section
    // order.
    let mut indexed: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| {
            e.meta.kind != Kind::Skill
                && shown_parts.get(e.id()).is_some_and(|ps| ps.iter().any(|p| p.line.is_none()))
        })
        .collect();
    let section_of = |e: &Entry| SECTIONS.iter().position(|(k, _)| *k == e.meta.kind);
    indexed.sort_by(|a, b| section_of(a).cmp(&section_of(b)).then_with(|| in_order(a, b)));
    if !indexed.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Index".into());
        for e in indexed {
            for p in shown_parts[e.id()].iter().filter(|p| p.line.is_none()) {
                push_part(p, &mut lines, &mut out);
            }
        }
    }
    // The skills of this place: the repo's own (backbone requirement BB-8, listed where they are) and the stack's development
    // skills (installed per checkout for harnesses that read a skills dir); listed so every harness finds them. A
    // skill every run has installed is listed where it has a line, its line being nowhere else (review r1, F3).
    let here: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| {
            e.meta.kind == Kind::Skill
                && (matches!(e.meta.origin, crate::model::Origin::InRepo { .. })
                    || !user_level(e)
                    || has_line(e))
        })
        // A child's file beside a place's lists only the skills with a line for it (the place's file lists them all).
        .filter(|e| !beyond || has_line(e))
        .collect();
    if !here.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        lines.push("# Skills here".into());
        lines.push(String::new());
        // A skill with lines for this file's readers shows them in place of its hook, one bullet each with its own
        // label (sol-loop r1, S3), after its id, which `lords show` opens (review r1, F4); its file follows from its
        // name as before, or is named.
        let mut items = Vec::new();
        for (e, text, name) in index_items(&here) {
            let shown: Vec<String> = shown_parts
                .get(e.id())
                .into_iter()
                .flatten()
                .filter(|p| p.line.is_some())
                .map(|p| part_line(p, ctx, stacks, &development))
                .collect();
            for l in &shown {
                items.push((e, l.trim_start_matches("- ").to_string(), name.clone()));
            }
            if shown.is_empty() {
                items.push((e, text, name));
            }
        }
        push_index(&items, ctx, &mut lines, &mut out);
    }
    // Memory: an index, not text. Each harness reads the notes on demand (docs/load-order.md); a note binds
    // nobody until it is promoted to an intent, rule or fact.
    let mut notes: Vec<&Entry> = live
        .iter()
        .copied()
        .filter(|e| e.meta.kind == Kind::Memory)
        .filter(|e| match &e.meta.origin {
            crate::model::Origin::Imported { store, .. } => !ctx.skip_stores.contains(store),
            _ => true,
        })
        .collect();
    // A live store's index is the file its agents write, one source (orchestrator, 30 Oct, item 3): it is named once.
    // Named from its declaration wherever its scope and audience reach and its harness doesn't load it by itself, so
    // a store with no note imported yet is named too (sol-loop r1, S1).
    let serves = |m: &crate::stack::MemoryStore| {
        m.audience.is_empty()
            || m.audience.iter().any(|a| {
                a == "all" || ctx.audience.iter().any(|c| format!("{c:?}").eq_ignore_ascii_case(a))
            })
    };
    // And by the rules memory notes follow: memory is private, so never in a public-only composition, and never for a
    // reader who is only `product` (sol-loop r2, S2, S3).
    let memory_here = !ctx.public_only
        && ctx.child.is_none()
        && ctx.roles.as_ref().is_none_or(|roles| roles.iter().any(|r| r != PRODUCT_ROLE));
    // Only an index that is a readable file is named (review r1, R2): a missing one is the plan's conflict and check's
    // error (`live_index_problem`), never a dead pointer.
    let live_here: BTreeSet<(&str, String)> = live_stores(stacks)
        .filter(|_| memory_here)
        .filter(|m| Scope::parse(&m.scope).is_some_and(|s| scope_in_layers(&s, &ctx.layers, false)))
        .filter(|m| serves(m) && !ctx.skip_stores.contains(&m.name))
        .filter(|m| live_index_problem(m).is_none())
        .map(|m| {
            let index = live_index(m);
            (
                m.name.as_str(),
                index.display().to_string().replace('/', std::path::MAIN_SEPARATOR_STR),
            )
        })
        .collect();
    notes.sort_by(|a, b| (a.rank(), a.id()).cmp(&(b.rank(), b.id())));
    // Where the reader's role is unknown, notes for one role stay out of the index; one line says where they are.
    // The place's default role is no unknown one: its notes stay in the index.
    let default_note = |e: &Entry| {
        ctx.role_dir.is_some() && ctx.inline_role().is_some_and(|d| e.meta.roles.contains(d))
    };
    let (role_notes, notes): (Vec<&Entry>, Vec<&Entry>) = notes
        .into_iter()
        .partition(|e| ctx.roles.is_none() && !e.meta.roles.is_empty() && !default_note(e));
    let pointer = role_pointer(&role_notes, ctx);
    if !notes.is_empty() || pointer.is_some() || !live_here.is_empty() {
        if !lines.is_empty() {
            lines.push(String::new());
        }
        let mut section: Vec<String> =
            vec!["# Memory".into(), String::new(), MEMORY_INTRO.into(), String::new()];
        for (name, index) in &live_here {
            section
                .push(format!("- {name}: its index is `{index}`, which its agents keep current"));
        }
        let mut found = Composed::default();
        push_index(&index_items(&notes), ctx, &mut section, &mut found);
        if let Some(p) = pointer {
            section.push(p);
        }
        // With a memory file the section goes there whole, and one line here names it (the Lords owner, 2 Nov).
        if let Some(file) = &ctx.memory_file {
            out.memory = Some(format!("{BEGIN}\n{HEADER}\n{}\n{END}\n", section.join("\n")));
            lines.extend(["# Memory".into(), String::new(), format!("Notes agents wrote down earlier are listed in `{}`. Read a note's file when its topic comes up; notes are not rules.", shown(file, ctx))]);
        } else {
            for s in found.sources.iter_mut() {
                s.line += lines.len();
            }
            out.sources.append(&mut found.sources);
            out.ids.append(&mut found.ids);
            lines.append(&mut section);
        }
    }
    // A child's file names its role even with nothing else: the place's file's labels then say what binds it.
    let child = ctx.child.zip(ctx.roles.as_deref().and_then(|r| r.first()));
    if out.ids.is_empty() && lines.is_empty() && child.is_none() {
        return out;
    }
    // Two header lines precede the composed lines, and the opener where an entry goes by its id.
    let mut header = 2;
    if opens || child.is_some() {
        let mut opener: Vec<String> =
            child.map(|(start, r)| child_intro(r, start)).into_iter().collect();
        if opens {
            opener.push(opener_line(ctx));
        }
        if lines.first().is_some_and(|l| !l.is_empty()) {
            opener.push(String::new());
        }
        header += opener.len();
        lines.splice(0..0, opener);
    }
    for s in out.sources.iter_mut() {
        s.line += header;
    }
    let mut text = format!("{BEGIN}\n{HEADER}\n");
    text.push_str(&lines.join("\n"));
    text.push('\n');
    text.push_str(END);
    text.push('\n');
    out.text = text;
    out
}

/// A managed block holding `body` (e.g. one include line).
pub fn block(body: &str) -> String {
    format!("{BEGIN}\n{HEADER}\n{}\n{END}\n", body.trim_end())
}

/// A composed block with `pre` first, right after the header (a repo file's tracked-instructions line).
pub fn with_preamble(text: &str, pre: &str) -> String {
    let head = format!("{BEGIN}\n{HEADER}\n");
    match text.strip_prefix(&head) {
        Some(rest) => format!("{head}{}\n\n{rest}", pre.trim_end()),
        None => format!("{}\n\n{text}", pre.trim_end()),
    }
}

/// Where a file's managed block is: from the start of its begin-marker line to the end of its end-marker line's
/// text, before that line's own line ending. Markers count only as whole lines (a sentence quoting one is owner
/// text). Anything but one begin line before one end line is an error: the file is no longer ours to edit.
fn block_span(text: &str) -> Result<Option<(usize, usize)>, String> {
    let (mut begins, mut ends) = (Vec::new(), Vec::new());
    let mut at = 0;
    for line in text.split_inclusive('\n') {
        let content = line.trim_end_matches('\n').trim_end_matches('\r');
        // A byte-order mark before the first line belongs to the owner's text, not to the marker.
        let bom =
            if at == 0 && content.starts_with('\u{feff}') { '\u{feff}'.len_utf8() } else { 0 };
        let content = &content[bom..];
        if content == BEGIN {
            begins.push(at + bom);
        }
        if content == END {
            ends.push(at + bom + content.len());
        }
        at += line.len();
    }
    match (begins.as_slice(), ends.as_slice()) {
        ([], []) => Ok(None),
        ([b], [e]) if b < e => Ok(Some((*b, *e))),
        _ => Err(format!(
            "{} begin and {} end marker lines, not one managed block; fix the file by hand, sync leaves it alone",
            begins.len(),
            ends.len()
        )),
    }
}

/// Puts a block into a file's text: between its marker lines, else appended. `replace` drops the text outside.
/// Every byte outside the block stays as it was, the line ending after the end marker (or its absence) included.
/// An error when the file's markers are broken, or the block itself carries marker lines (a quoted tracked file).
pub fn place_block(current: &str, block: &str, replace: bool) -> Result<String, String> {
    if !block.is_empty() && block_span(block)?.is_none() {
        return Err("the composed block has no marker lines".into());
    }
    if replace {
        return Ok(block.to_string());
    }
    if let Some((b, e)) = block_span(current)? {
        let after = &current[e..];
        // Removing the block keeps every byte around it, the end marker's own line ending included (Sol review
        // r2, R2-18).
        if block.is_empty() {
            return Ok(format!("{}{after}", &current[..b]));
        }
        let body = block.strip_suffix('\n').unwrap_or(block);
        return Ok(format!("{}{body}{after}", &current[..b]));
    }
    if block.is_empty() || current.is_empty() {
        return Ok(format!("{current}{block}"));
    }
    let sep = if current.ends_with("\n\n") {
        ""
    } else if current.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    };
    Ok(format!("{current}{sep}{block}"))
}

/// The managed block currently in a file, if it has exactly one.
pub fn current_block(text: &str) -> Option<&str> {
    block_bounds(text).map(|(b, e)| &text[b..e])
}

/// Where a file's one managed block lies, as byte offsets: from its begin marker's line to the end of its end marker's
/// line, that line's ending included. `None` without exactly one block.
pub fn block_bounds(text: &str) -> Option<(usize, usize)> {
    let (b, e) = block_span(text).ok()??;
    let after = &text[e..];
    let nl = if after.starts_with("\r\n") {
        2
    } else if after.starts_with('\n') {
        1
    } else {
        0
    };
    Some((b, e + nl))
}
